import{_ as e}from"./chunks/pohledy.D03Xp3rL.js";import{_ as a,o,c as l,aa as s}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/cs/tickets/konfig_mrizky.png",r="/buildary-help-preview/media/cs/tickets/sprava_pohledu.png",n="/buildary-help-preview/media/cs/tickets/svisla_trojtecka.png",p="/buildary-help-preview/media/cs/tickets/presun_sloupce.png",d="/buildary-help-preview/media/cs/tickets/razeni.png",z=JSON.parse('{"title":"Přizpůsobit pohledy","description":"","frontmatter":{"title":"Přizpůsobit pohledy"},"headers":[],"relativePath":"tickets/taskviews.md","filePath":"tickets/taskviews.md","lastUpdated":1794209661000}'),u={name:"tickets/taskviews.md"};function h(k,t,c,v,m,y){return o(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="prizpusobit-pohledy" tabindex="-1">Přizpůsobit pohledy <a class="header-anchor" href="#prizpusobit-pohledy" aria-label="Permalink to &quot;Přizpůsobit pohledy&quot;">​</a></h1><p>Mřížku v Seznamu úkolů si nastavíte podle sebe: vyberete sloupce, změníte jejich pořadí, úkoly seřadíte a seskupíte. Takové nastavení uložíte jako <strong>pohled</strong> a mezi uloženými pohledy pak jedním kliknutím přepínáte.</p><p>Pohledy si každý uživatel nastavuje sám pro sebe. Jak pracovat se seznamem a filtry, popisuje <a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a>.</p><h2 id="tlacitka-pro-pohledy" tabindex="-1">Tlačítka pro pohledy <a class="header-anchor" href="#tlacitka-pro-pohledy" aria-label="Permalink to &quot;Tlačítka pro pohledy&quot;">​</a></h2><p>Nad mřížkou vpravo jsou tři tlačítka:</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Lišta nad mřížkou s vyznačeným výběrem pohledu, tlačítkem Správa pohledů a menu Další nastavení" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Tlačítko</th><th>K čemu slouží</th></tr></thead><tbody><tr><td>výběr pohledu (například <strong>Základní pohled</strong>)</td><td>přepíná mezi uloženými pohledy</td></tr><tr><td>ikona tabulky – správa pohledů</td><td>vytvoří, uloží, přejmenuje nebo odstraní pohled a nastaví výchozí pohled</td></tr><tr><td>menu <strong>⋮</strong></td><td>zapne filtrační řádek a seskupovací panel a otevře <strong>Výběr sloupců</strong></td></tr></tbody></table><h2 id="prepnout-pohled" tabindex="-1">Přepnout pohled <a class="header-anchor" href="#prepnout-pohled" aria-label="Permalink to &quot;Přepnout pohled&quot;">​</a></h2><p>Rozbalte výběr pohledu a klikněte na pohled, který chcete použít. Na stavbě je připraveno pět pohledů:</p><ul><li><strong>Základní pohled</strong>,</li><li><strong>Zpožděné úkoly dle Priority</strong>,</li><li><strong>Neukončené Neshody, vady a nedodělky seskupeny dle Priority</strong>,</li><li><strong>Seskupeno dle Kategorie a Ukončeno</strong>,</li><li><strong>Seskupeno dle Priority a Kategorie</strong>.</li></ul><p>Ve výběru jsou i pohledy, které jste si vytvořili sami.</p><figure class="shot" style="--w:560px;"><img src="'+e+'" alt="Rozbalený výběr pohledů s pěti připravenými pohledy" loading="lazy"></figure><h2 id="ulozit-vlastni-pohled" tabindex="-1">Uložit vlastní pohled <a class="header-anchor" href="#ulozit-vlastni-pohled" aria-label="Permalink to &quot;Uložit vlastní pohled&quot;">​</a></h2><p>Pohled si uložte, když si mřížku upravíte a chcete se k nastavení vracet – sloupce, jejich pořadí, řazení a seskupení.</p><ol><li>Upravte mřížku – viz <a href="#nastavit-mrizku">Nastavit mřížku</a>.</li><li>Klikněte na ikonu správy pohledů a zvolte <strong>Vytvořit nový</strong>.</li><li>Pohled pojmenujte a uložte.</li></ol><figure class="shot" style="--w:420px;"><img src="'+r+'" alt="Rozbalená správa pohledů s volbami Vytvořit nový, Uložit, Přejmenovat, Nastavit jako výchozí, Export pohledu, Import pohledu a Odstranit" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Volba</th><th>Co udělá</th></tr></thead><tbody><tr><td><strong>Vytvořit nový</strong></td><td>uloží současné nastavení mřížky jako nový pohled</td></tr><tr><td><strong>Uložit</strong></td><td>uloží změny do právě zvoleného pohledu</td></tr><tr><td><strong>Přejmenovat</strong></td><td>změní název pohledu</td></tr><tr><td><strong>Nastavit jako výchozí</strong></td><td>pohled se otevře pokaždé, když přijdete na Seznam úkolů</td></tr><tr><td><strong>Odstranit</strong></td><td>smaže pohled</td></tr></tbody></table><h2 id="nastavit-mrizku" tabindex="-1">Nastavit mřížku <a class="header-anchor" href="#nastavit-mrizku" aria-label="Permalink to &quot;Nastavit mřížku&quot;">​</a></h2><h3 id="vybrat-sloupce" tabindex="-1">Vybrat sloupce <a class="header-anchor" href="#vybrat-sloupce" aria-label="Permalink to &quot;Vybrat sloupce&quot;">​</a></h3><p>V menu <strong>⋮</strong> zvolte <strong>Výběr sloupců</strong> a zaškrtněte sloupce, které chcete v mřížce vidět. Například sloupec <strong>Související úkoly</strong> ukáže vazby úkolů na jiné úkoly a na záznamy v deníku – viz <a href="/buildary-help-preview/tickets/task_new#souvisejici-ukol">Zadat úkol</a>.</p><figure class="shot" style="--w:320px;"><img src="'+n+'" alt="Menu Další nastavení s volbami Zapnout filtrační řádek, Seskupovací panel a Výběr sloupců" loading="lazy"></figure><h3 id="presunout-sloupec" tabindex="-1">Přesunout sloupec <a class="header-anchor" href="#presunout-sloupec" aria-label="Permalink to &quot;Přesunout sloupec&quot;">​</a></h3><p>Chyťte sloupec myší za záhlaví a přetáhněte ho doleva nebo doprava na nové místo.</p><h3 id="seskupit-ukoly" tabindex="-1">Seskupit úkoly <a class="header-anchor" href="#seskupit-ukoly" aria-label="Permalink to &quot;Seskupit úkoly&quot;">​</a></h3><ol><li>V menu <strong>⋮</strong> zapněte <strong>Seskupovací panel</strong>. Nad mřížkou se objeví prázdný řádek.</li><li>Přetáhněte do něj záhlaví sloupce, podle kterého chcete úkoly seskupit, například <strong>Priorita</strong>.</li><li>Pro další úroveň seskupení přetáhněte další sloupec. Pořadí skupin změníte přetažením v panelu, křížkem skupinu zrušíte.</li></ol><figure class="shot" style="--w:760px;"><img src="'+p+'" alt="Seskupovací panel se sloupci Ukončeno, Priorita a Kategorie a přetahování sloupce Stav" loading="lazy"></figure><h3 id="seradit-ukoly" tabindex="-1">Seřadit úkoly <a class="header-anchor" href="#seradit-ukoly" aria-label="Permalink to &quot;Seřadit úkoly&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Akce</th><th>Výsledek</th></tr></thead><tbody><tr><td>klikněte na název sloupce</td><td>řazení vzestupně (šipka nahoru)</td></tr><tr><td>klikněte znovu</td><td>řazení sestupně (šipka dolů)</td></tr><tr><td>klikněte potřetí</td><td>řazení vypnuto</td></tr><tr><td><strong>Shift</strong> + klik na další sloupec</td><td>přidá sloupec do řazení, číslo u šipky ukazuje pořadí</td></tr></tbody></table><p>Stejně se Shift + klikem mění směr řazení dalších sloupců a vypíná se řazení jen jednoho z nich.</p><figure class="shot" style="--w:560px;"><img src="'+d+'" alt="Řazení podle tří sloupců s šipkami a čísly pořadí" loading="lazy"></figure><div class="tip custom-block"><p class="custom-block-title">Zrušit řazení všech sloupců</p><p>Klikněte (bez Shiftu) na sloupec, který je řazený sestupně – řazení ostatních sloupců zmizí a dalším kliknutím zrušíte i toto. Jsou-li všechny sloupce řazené vzestupně, klikněte na kterýkoli z nich dvakrát.</p></div><h3 id="filtrovat-ve-sloupcich" tabindex="-1">Filtrovat ve sloupcích <a class="header-anchor" href="#filtrovat-ve-sloupcich" aria-label="Permalink to &quot;Filtrovat ve sloupcích&quot;">​</a></h3><p>Filtrační řádek a filtry ve sloupcích popisuje <a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a>.</p>',33)])])}const f=a(u,[["render",h]]);export{z as __pageData,f as default};
